export function powxN(base: number, exponent: number): string[] {
let n=Math.abs(exponent),x=BigInt(base),result=1n;while(n){if(n%2)result*=x;x*=x;n=Math.floor(n/2);}if(exponent>=0)return [String(result),'1'];return result<0?['-1',String(-result)]:['1',String(result)];
}
